  static Label Label(string text,float size,FontStyle style=FontStyle.Regular){return new Label{Text=text,Dock=DockStyle.Fill,Font=new Font("Segoe UI",size,style),ForeColor=Theme.Text,BackColor=Color.Transparent};}
