  internal bool InspectionReady{get{return root!=null;}}
  internal async void SetRoot(string value){await SetRootAsync(value);}
  async Task SetRootAsync(string value){int ticket=++inspection;root=null;Buttons();try{var detected=await Task.Run(()=>{string path=Paths.ValidateRoot(value);return Tuple.Create(path,installer.Inspect(path));});if(ticket!=inspection||IsDisposed)return;root=detected.Item1;inventory=detected.Item2;location.Text=root;for(int i=0;i<4;++i){var m=catalog.Modules[i];selected[i].Checked=inventory.Plugins.Any(x=>x.Module==m.Id)||inventory.LegacyHost&&inventory.LegacyEnabled[m.Id]||inventory.Plugins.Count==0&&!inventory.LegacyHost;var existing=inventory.Plugins.FirstOrDefault(x=>x.Module==m.Id&&x.Path.Equals("Plugins/"+m.FileName,StringComparison.OrdinalIgnoreCase));if(existing!=null&&existing.Version!="unknown"&&ReleaseRules.Numeric(existing.Version)>ReleaseRules.Numeric(targets[m.Id].Version)){selected[i].Checked=false;}}
    hint.Text=inventory.LegacyHost?"Older COT found. Keep all enabled modules selected for its one-time conversion.":"Mod Manager found. Close MMC and the game before changing files.";if(fixture==null)await Task.Run(()=>Locator.Remember(detected.Item1));RefreshVersions();}
   catch(Exception e){if(ticket!=inspection||IsDisposed)return;root=null;hint.Text=Paths.Explain(e);Note(hint.Text);}Buttons();}
  void FitLayout(){if(layout==null||fitting)return;fitting=true;try{float scale=layoutScale>0?layoutScale:DeviceDpi/96f;if(scale<=0)scale=1;bool compact=ClientSize.Height/scale<580;float[] heights=compact?new[]{36f,64f,26f,0f,0f,5f,44f,32f}:new[]{48f,82f,31f,0f,35f,8f,47f,30f};for(int i=0;i<heights.Length;i++)if(i!=3&&i!=6&&Math.Abs(layout.RowStyles[i].Height-heights[i]*scale)>.1f)layout.RowStyles[i].Height=heights[i]*scale;layout.Padding=new Padding((int)(18*scale),(int)(10*scale),(int)(18*scale),(int)(10*scale));if(apply.Parent!=null){layout.RowStyles[6].Height=apply.Parent.Controls.Cast<Control>().Max(c=>c.Height+c.Margin.Vertical)+apply.Parent.Padding.Vertical+apply.Parent.Margin.Vertical+8;}if(moduleViewport!=null){int minimum=(int)(310*scale);moduleCards.Dock=DockStyle.None;moduleCards.Anchor=AnchorStyles.Top|AnchorStyles.Left;moduleCards.Width=Math.Max(0,moduleViewport.ClientSize.Width);moduleCards.Height=Math.Max(minimum,moduleViewport.ClientSize.Height);moduleViewport.AutoScrollMinSize=new Size(0,minimum);}}finally{fitting=false;}}
  protected override void WndProc(ref Message message){base.WndProc(ref message);if(message.Msg==0x02e0)BeginInvoke(new Action(FitLayout));}
  void RefreshVersions(){if(inventory==null)return;for(int i=0;i<4;++i){var m=catalog.Modules[i];var current=inventory.Plugins.FirstOrDefault(x=>x.Module==m.Id&&x.Path.Equals("Plugins/"+m.FileName,StringComparison.OrdinalIgnoreCase));string target=targets[m.Id].Version;versions[i].Text=inventory.Status(m)+(current!=null&&current.Sha256==targets[m.Id].DllSha256?" · keeping this version":" → "+target);}}
  void Buttons(){bool valid=root!=null&&location.Text==root;foreach(var item in new Control[]{browse,apply,updates,backups,remove,location})item.Enabled=!busy;foreach(var choice in selected)choice.Enabled=!busy;apply.Enabled=!busy&&valid&&selected.Any(x=>x.Checked);backups.Enabled=remove.Enabled=!busy&&valid;close.Enabled=!busy||!committing;close.Text=busy?"Cancel":"Close";}
  void Note(string message){if(InvokeRequired){BeginInvoke(new Action<string>(Note),message);return;}status.Text=message;System.Threading.ThreadPool.QueueUserWorkItem(o=>{try{lock(logSync){string path=Ace.DynastyCOT.UserStorage.Current.Resolve("Setup/Logs/collection.log");Directory.CreateDirectory(Path.GetDirectoryName(path));if(File.Exists(path)&&new FileInfo(path).Length>2*1024*1024)File.WriteAllText(path,"");File.AppendAllText(path,DateTime.UtcNow.ToString("o")+" "+message+Environment.NewLine);}}catch(IOException){}catch(UnauthorizedAccessException){}});}
  async Task Run(Func<Task> work){if(busy)return;busy=true;committing=false;cancellation=new CancellationTokenSource();progress.Visible=true;Buttons();try{await work();}catch(OperationCanceledException){Note("Cancelled. Existing installed files were not changed.");}catch(Exception e){string message=Paths.Explain(e);Note(message);ShowFailure(e,message);}finally{busy=false;committing=false;cancellation.Dispose();progress.Visible=false;Buttons();}}
  Dictionary<string,string> Review(Plan plan){var unknown=installer.Review(plan);bool ask=unknown.Count>0||plan.Inventory.LegacyHost;if(ask){string text=plan.Inventory.LegacyHost?"The older COT host will be backed up. Its enabled modules will become independent plugins. Settings/history folders stay in place.\r\n\r\n":"";if(unknown.Count>0)text+="These plugin copies are not in the known-hash catalog. Back up and replace/remove these exact files?\r\n"+String.Join("\r\n",unknown.Select(x=>x.Path+"\r\nSHA-256: "+x.Sha256));if(MessageBox.Show(this,text,"Review migration",MessageBoxButtons.OKCancel,MessageBoxIcon.Information)!=DialogResult.OK)return null;}return unknown.ToDictionary(x=>x.Path,x=>x.Sha256);}
  async Task Install(){await Run(async()=>{
   string chosen=root;Paths.Closed(fixture,chosen);var wanted=new Dictionary<string,ModuleRelease>();for(int i=0;i<4;++i)if(selected[i].Checked)wanted.Add(catalog.Modules[i].Id,targets[catalog.Modules[i].Id]);
   var fresh=await Task.Run(()=>installer.Inspect(chosen));if(fresh.LegacyHost&&catalog.Modules.Any(m=>fresh.LegacyEnabled[m.Id]&&!wanted.ContainsKey(m.Id)))throw new IOException("Keep all enabled older-COT modules selected for migration, or explicitly remove unwanted ones first.");
   string cache=fixture!=null?Path.Combine(fixture.Parent,"Downloads"):Ace.DynastyCOT.UserStorage.Current.Resolve("Downloads");
   var payloads=await Task.Run(()=>{var list=new List<PreparedModule>();foreach(var entry in wanted){var m=catalog.Get(entry.Key);if(fresh.Plugins.Any(x=>x.Path.Equals("Plugins/"+m.FileName,StringComparison.OrdinalIgnoreCase)&&x.Sha256==entry.Value.DllSha256))continue;list.Add(downloads.Prepare(m,entry.Value,cache,cancellation.Token,Note));}return list;});
   cancellation.Token.ThrowIfCancellationRequested();var older=new HashSet<string>(wanted.Where(x=>fresh.Plugins.Any(p=>p.Path.Equals("Plugins/"+catalog.Get(x.Key).FileName,StringComparison.OrdinalIgnoreCase)&&p.Version!="unknown"&&ReleaseRules.Numeric(p.Version)>ReleaseRules.Numeric(x.Value.Version))).Select(x=>x.Key));if(older.Count>0&&MessageBox.Show(this,"You selected older versions of "+String.Join(", ",older)+". Downgrade those plugins? Settings/history are kept.","Confirm older versions",MessageBoxButtons.OKCancel)!=DialogResult.OK){Note("Downgrade cancelled.");return;}var plan=await Task.Run(()=>installer.Install(chosen,wanted,payloads,older));Note(plan.Summary);var reviewed=Review(plan);if(reviewed==null){Note("Migration cancelled. No installed files changed.");return;}committing=true;Buttons();await Task.Run(()=>installer.Execute(plan,reviewed,Note));Note("Done. Open MMC and launch normally. Your backup is under Backups.");await SetRootAsync(chosen);
  });}
  async Task Updates(){await Run(async()=>{
   Note("Checking module releases. Nothing is being downloaded or installed.");
   var checks=catalog.Modules.Select(module=>Task.Run(()=>{try{return new KeyValuePair<string,List<ModuleRelease>>(module.Id,downloads.Check(module,cancellation.Token));}catch(IOException error){Note(error.Message);return new KeyValuePair<string,List<ModuleRelease>>(module.Id,new List<ModuleRelease>());}})).ToArray();
   var choices=(await Task.WhenAll(checks)).ToDictionary(x=>x.Key,x=>x.Value);

   using(var dialog=new UpdateForm(catalog,inventory,choices,(index,release)=>{var module=catalog.Modules[index];targets[module.Id]=release;selected[index].Checked=true;RefreshVersions();Note(module.Title+" "+release.Version+" selected. Click Install / Update to apply it.");})){dialog.Icon=Icon;dialog.ShowDialog(this);}
   Note("Update check finished. Nothing was installed.");
  });}
  async Task Remove(bool all){if(root==null)return;var ids=catalog.Modules.Where((m,i)=>all||selected[i].Checked).Select(x=>x.Id).ToArray();if(ids.Length==0)return;if(MessageBox.Show(this,"Remove "+String.Join(", ",ids.Select(x=>catalog.Get(x).Title))+"? Settings and histories are kept. A backup will be made.","Remove modules",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;await Run(async()=>{var plan=await Task.Run(()=>installer.Remove(root,ids));var reviewed=Review(plan);if(reviewed==null)return;committing=true;Buttons();await Task.Run(()=>installer.Execute(plan,reviewed,Note));await SetRootAsync(root);Note("Selected plugins removed. Settings and history were kept.");});}
  async Task Backups(){if(root==null)return;var available=await Task.Run(()=>installer.Backups(root));if(available.Count==0){Note("No collection backups yet. Older COT backups remain in their original folder.");return;}Backup chosen=null;using(var dialog=new Form{Text="Restore a backup",ClientSize=new Size(680,290),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background,ForeColor=Theme.Text,Font=Font}){var list=new ListBox{Dock=DockStyle.Fill,BackColor=Theme.Surface,ForeColor=Theme.Text};list.Items.AddRange(available.Cast<object>().ToArray());list.SelectedIndex=0;dialog.Controls.Add(list);var button=new Button{Text="Restore selected backup",Dock=DockStyle.Bottom,Height=42};dialog.Controls.Add(button);button.Click+=(s,e)=>{chosen=(Backup)list.SelectedItem;dialog.Close();};dialog.ShowDialog(this);}if(chosen==null||MessageBox.Show(this,"Restore the plugin versions in this backup? Settings/history are kept. Restore newer backups first.","Restore backup",MessageBoxButtons.OKCancel)!=DialogResult.OK)return;await Run(async()=>{committing=true;Buttons();await Task.Run(()=>installer.Restore(root,chosen.Directory));await SetRootAsync(root);Note("Backup restored. Restart MMC and the game.");});}
  void ShowFailure(Exception failure,string message){
   bool denied=false;for(var cause=failure;cause!=null;cause=cause.InnerException)if(cause is UnauthorizedAccessException)denied=true;
   if(!denied||fixture!=null){ShowText("Operation stopped",message);return;}
   using(var dialog=new Form{Text="Permission needed",ClientSize=new Size(720,350),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background,Font=Font}){
    var text=new TextBox{Text=message+Environment.NewLine+Environment.NewLine+"You can move MMC to a folder you can write to, or reopen setup with administrator permission. Review your module choices again before installing.",Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Theme.Surface,ForeColor=Theme.Text};dialog.Controls.Add(text);
    var retry=new Button{Text="Reopen setup as administrator",Dock=DockStyle.Bottom,Height=40};dialog.Controls.Add(retry);retry.Click+=(s,e)=>{try{string arguments=root==null?"":"--manager \""+root+"\"";Process.Start(new ProcessStartInfo(Application.ExecutablePath,arguments){UseShellExecute=true,Verb="runas"});dialog.Close();}catch(System.ComponentModel.Win32Exception error){Note(error.NativeErrorCode==1223?"Administrator request cancelled. Installed files are unchanged.":error.Message);}};dialog.ShowDialog(this);
   }
  }
  void ShowText(string title,string text){using(var dialog=new Form{Text=title,ClientSize=new Size(800,480),StartPosition=FormStartPosition.CenterParent,Icon=Icon,BackColor=Theme.Background}){var box=new TextBox{Text=DisplayText.Notes(text),Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Font=new Font("Consolas",9),BackColor=Theme.Surface,ForeColor=Theme.Text};dialog.Controls.Add(box);dialog.ShowDialog(this);}}
  internal void SetPreviewScale(float value){layoutScale=value;FitLayout();}
  internal void AuditLayout(){FitLayout();PerformLayout();foreach(Control control in new[]{apply,close,remove,backups,updates}){if(!control.Visible||control.Parent.RectangleToScreen(control.Parent.ClientRectangle).Contains(control.RectangleToScreen(control.ClientRectangle))==false)throw new IOException("Footer action is clipped: "+control.Text+" bounds="+control.Bounds+" parent="+control.Parent.ClientRectangle+" window="+ClientSize+" scale="+layoutScale+" row="+layout.RowStyles[6].Height+" rows="+String.Join(",",layout.GetRowHeights()));var measured=TextRenderer.MeasureText(control.Text,control.Font);if(measured.Width>control.Width||measured.Height>control.Height)throw new IOException("Footer label is clipped: "+control.Text);}foreach(var label in descriptions){if(!label.Parent.ClientRectangle.Contains(label.Bounds))throw new IOException("Description bounds leave their card: "+label.Text+" label="+label.Bounds+" parent="+label.Parent.ClientRectangle+" card="+label.Parent.Parent.ClientRectangle+" scale="+layoutScale);var size=TextRenderer.MeasureText(label.Text,label.Font,new Size(label.Width-label.Padding.Horizontal,Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.TextBoxControl);if(size.Height>label.Height-label.Padding.Vertical)throw new IOException("Module description is clipped: "+label.Text+" measured="+size+" bounds="+label.Bounds+" scale="+layoutScale);}}
 }
 internal static class Locator {
  static string Preference{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"DynastyCOT","last-manager.txt");}}
  internal static void Remember(string root){try{Directory.CreateDirectory(Path.GetDirectoryName(Preference));File.WriteAllText(Preference,root);}catch(IOException){}catch(UnauthorizedAccessException){}}
  internal static string Find(){try{if(File.Exists(Preference))return Paths.ValidateRoot(File.ReadAllText(Preference));}catch(IOException){}catch(ArgumentException){}
   foreach(var process in Process.GetProcessesByName("MMCModManager"))using(process)try{return Paths.ValidateRoot(Path.GetDirectoryName(process.MainModule.FileName));}catch(System.ComponentModel.Win32Exception){}catch(InvalidOperationException){}catch(IOException){}
   var starts=new List<string>{AppDomain.CurrentDomain.BaseDirectory,Environment.CurrentDirectory,Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Downloads"),Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory)};
   foreach(var drive in DriveInfo.GetDrives())if(drive.DriveType==DriveType.Fixed)foreach(string part in new[]{@"Apps\CFB 27\MMC",@"Games\CFB 27\MMC",@"MMC",@"Tools\MMC"})starts.Add(Path.Combine(drive.Name,part));
   var found=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var visited=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string start in starts.Distinct(StringComparer.OrdinalIgnoreCase))for(var directory=new DirectoryInfo(start);directory!=null;directory=directory.Parent)try{if(!visited.Add(directory.FullName))continue;var valid=Paths.ValidateRoot(directory.FullName);found.Add(valid);break;}catch(IOException){}catch(UnauthorizedAccessException){}return found.Count==1?found.First():null;
  }
 }
